/**
 * @fileoverview Barrel file for the git_init tool.
 * Exports the registration function and the state accessor initializer.
 */

export {
  registerGitInitTool,
  initializeGitInitStateAccessors,
} from "./registration.js";
// Export types if needed elsewhere, e.g.:
// export type { GitInitInput, GitInitResult } from './logic.js';

import { exec } from "child_process";
import fs from "fs/promises";
import path from "path";
import { promisify } from "util";
import { z } from "zod";
// Import utils from barrel (logger from ../utils/internal/logger.js)
import { logger } from "../../../utils/index.js";
// Import utils from barrel (RequestContext from ../utils/internal/requestContext.js)
import { BaseErrorCode, McpError } from "../../../types-global/errors.js"; // Keep direct import for types-global
import { RequestContext } from "../../../utils/index.js";
// Import utils from barrel (sanitization from ../utils/security/sanitization.js)
import { sanitization } from "../../../utils/index.js";

const execAsync = promisify(exec);

// Define the input schema for the git_init tool using Zod
export const GitInitInputSchema = z.object({
  path: z
    .string()
    .min(1)
    .optional()
    .default(".")
    .describe(
      "Path where the new Git repository should be initialized. Can be relative or absolute. If relative or '.', it resolves against the directory set via `git_set_working_dir` for the session. If absolute, it's used directly. If omitted, defaults to '.' (resolved against session git working directory).",
    ),
  initialBranch: z
    .string()
    .optional()
    .describe(
      "Optional name for the initial branch (e.g., 'main'). Uses Git's default if not specified.",
    ),
  bare: z
    .boolean()
    .default(false)
    .describe("Create a bare repository (no working directory)."),
  quiet: z
    .boolean()
    .default(false)
    .describe(
      "Only print error and warning messages; all other output will be suppressed.",
    ),
});

// Infer the TypeScript type from the Zod schema
export type GitInitInput = z.infer<typeof GitInitInputSchema>;

// Define the structure for the JSON output
export interface GitInitResult {
  success: boolean;
  message: string;
  path: string; // The path where the repo was initialized
  gitDirExists: boolean; // Confirms the .git directory was created (or equivalent for bare)
}

/**
 * Executes the 'git init' command to initialize a new Git repository.
 *
 * @param {GitInitInput} input - The validated input object.
 * @param {RequestContext} context - The request context for logging and error handling.
 * @returns {Promise<GitInitResult>} A promise that resolves with the structured init result.
 * @throws {McpError} Throws an McpError if path validation fails or the git command fails unexpectedly.
 */
export async function gitInitLogic(
  input: GitInitInput,
  context: RequestContext,
): Promise<GitInitResult> {
  const operation = "gitInitLogic";
  logger.debug(`Executing ${operation}`, { ...context, input });

  let targetPath: string;
  try {
    // Sanitize the provided absolute path
    targetPath = sanitization.sanitizePath(input.path, {
      allowAbsolute: true,
    }).sanitizedPath;
    logger.debug("Sanitized path", {
      ...context,
      operation,
      sanitizedPath: targetPath,
    });

    // Ensure the target directory exists before trying to init inside it
    // git init creates the directory if it doesn't exist, but we might want to ensure the parent exists
    const parentDir = path.dirname(targetPath);
    try {
      await fs.access(parentDir, fs.constants.W_OK); // Check write access in parent
    } catch (accessError: any) {
      logger.error(`Parent directory check failed for ${targetPath}`, {
        ...context,
        operation,
        error: accessError.message,
      });
      if (accessError.code === "ENOENT") {
        throw new McpError(
          BaseErrorCode.VALIDATION_ERROR,
          `Parent directory does not exist: ${parentDir}`,
          { context, operation },
        );
      }
      throw new McpError(
        BaseErrorCode.VALIDATION_ERROR,
        `Cannot access parent directory: ${parentDir}. Error: ${accessError.message}`,
        { context, operation },
      );
    }
  } catch (error) {
    logger.error("Path validation or sanitization failed", {
      ...context,
      operation,
      error,
    });
    if (error instanceof McpError) throw error;
    throw new McpError(
      BaseErrorCode.VALIDATION_ERROR,
      `Invalid path: ${error instanceof Error ? error.message : String(error)}`,
      { context, operation, originalError: error },
    );
  }

  try {
    // Construct the git init command
    let command = `git init`;
    if (input.quiet) {
      command += " --quiet";
    }
    if (input.bare) {
      command += " --bare";
    }
    // Determine the initial branch name, defaulting to 'main' if not provided
    const branchNameToUse = input.initialBranch || "main";
    command += ` -b "${branchNameToUse.replace(/"/g, '\\"')}"`;

    // Add the target directory path at the end
    command += ` "${targetPath}"`;

    logger.debug(`Executing command: ${command}`, { ...context, operation });

    const { stdout, stderr } = await execAsync(command);

    if (stderr && !input.quiet) {
      // Log stderr as warning but proceed, as init might still succeed (e.g., reinitializing)
      logger.warning(`Git init command produced stderr`, {
        ...context,
        operation,
        stderr,
      });
    }
    if (stdout && !input.quiet) {
      // Log stdout at debug level for cleaner info logs
      logger.debug(`Git init command produced stdout`, {
        ...context,
        operation,
        stdout,
      });
    }

    // Verify .git directory exists (or equivalent for bare repo)
    const gitDirPath = input.bare ? targetPath : path.join(targetPath, ".git");
    let gitDirExists = false;
    try {
      await fs.access(gitDirPath);
      gitDirExists = true;
    } catch (e) {
      logger.warning(
        `Could not verify existence of ${gitDirPath} after git init`,
        { ...context, operation },
      );
    }

    const successMessage = `Successfully initialized Git repository in ${targetPath}`;
    logger.info(successMessage, {
      ...context,
      operation,
      path: targetPath,
      bare: input.bare,
      initialBranch: input.initialBranch || "default",
    });
    return {
      success: true,
      message: stdout.trim() || successMessage, // Return stdout to user if available
      path: targetPath,
      gitDirExists: gitDirExists,
    };
  } catch (error: any) {
    const errorMessage = error.stderr || error.message || "";
    logger.error(`Failed to execute git init command`, {
      ...context,
      operation,
      path: targetPath,
      error: errorMessage,
      stderr: error.stderr,
      stdout: error.stdout,
    });

    // Handle specific error cases
    if (
      errorMessage.toLowerCase().includes("already exists") &&
      errorMessage.toLowerCase().includes("git repository")
    ) {
      // Reinitializing is often okay, treat as success but mention it.
      logger.info(`Repository already exists, reinitialized: ${targetPath}`, {
        ...context,
        operation,
      });
      return {
        success: true, // Treat reinitialization as success
        message: `Reinitialized existing Git repository in ${targetPath}`,
        path: targetPath,
        gitDirExists: true, // Assume it exists if reinit message appears
      };
    }
    if (errorMessage.toLowerCase().includes("permission denied")) {
      throw new McpError(
        BaseErrorCode.FORBIDDEN,
        `Permission denied to initialize repository at: ${targetPath}. Error: ${errorMessage}`,
        { context, operation, originalError: error },
      );
    }

    // Generic internal error for other failures
    throw new McpError(
      BaseErrorCode.INTERNAL_ERROR,
      `Failed to initialize repository at: ${targetPath}. Error: ${errorMessage}`,
      { context, operation, originalError: error },
    );
  }
}

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import {
  CallToolResult,
  TextContent,
} from "@modelcontextprotocol/sdk/types.js";
import path from "path";
import { z } from "zod";
import { BaseErrorCode, McpError } from "../../../types-global/errors.js";
import {
  ErrorHandler,
  logger,
  requestContextService,
  sanitization,
} from "../../../utils/index.js";
import {
  GitInitInput,
  GitInitInputSchema,
  gitInitLogic,
  GitInitResult,
} from "./logic.js";

const TOOL_NAME = "git_init";
const TOOL_DESCRIPTION =
  "Initializes a new Git repository at the specified path. If path is relative or omitted, it resolves against the session working directory (if you have set the git_working_dir). Can optionally set the initial branch name and create a bare repository.";

const RegistrationSchema = GitInitInputSchema.extend({
  path: z.string().min(1).optional().default("."),
}).shape;

// --- Module-level State Accessors ---
// These will be populated by the initialize function called from server.ts
let _getWorkingDirectory: (
  sessionId: string | undefined,
) => string | undefined = () => undefined;
let _getSessionIdFromContext: (
  context: Record<string, any>,
) => string | undefined = () => undefined;

/**
 * Initializes state accessor functions for the git_init tool.
 * This function is called by the main server setup to provide the tool
 * with a way to access session-specific state (like the working directory)
 * without needing direct access to the server or transport layer internals.
 *
 * @param getWorkingDirectory - Function to retrieve the working directory for a given session ID.
 * @param getSessionIdFromContext - Function to extract the session ID from a tool's execution context.
 */
export function initializeGitInitStateAccessors(
  getWorkingDirectory: (sessionId: string | undefined) => string | undefined,
  getSessionIdFromContext: (context: Record<string, any>) => string | undefined,
): void {
  _getWorkingDirectory = getWorkingDirectory;
  _getSessionIdFromContext = getSessionIdFromContext;
  logger.debug(`State accessors initialized for ${TOOL_NAME}`);
}

/**
 * Registers the git_init tool with the MCP server.
 *
 * @param {McpServer} server - The McpServer instance to register the tool with.
 * @returns {Promise<void>}
 * @throws {Error} If registration fails.
 */
export const registerGitInitTool = async (server: McpServer): Promise<void> => {
  const operation = "registerGitInitTool";
  const context = requestContextService.createRequestContext({ operation });

  await ErrorHandler.tryCatch(
    async () => {
      server.tool<typeof RegistrationSchema>(
        TOOL_NAME,
        TOOL_DESCRIPTION,
        RegistrationSchema,
        async (validatedArgs, callContext): Promise<CallToolResult> => {
          // Removed explicit type for callContext
          const toolOperation = "tool:git_init";
          const requestContext = requestContextService.createRequestContext({
            operation: toolOperation,
            parentContext: callContext,
          });

          // Use the initialized accessor to get the session ID
          const sessionId = _getSessionIdFromContext(requestContext); // Pass the created context
          if (!sessionId && !path.isAbsolute(validatedArgs.path)) {
            // If path is relative, we NEED a session ID to resolve against a potential working dir
            logger.error(
              "Session ID is missing in context, cannot resolve relative path",
              requestContext,
            );
            throw new McpError(
              BaseErrorCode.INTERNAL_ERROR,
              "Session context is unavailable for relative path resolution.",
              { context: requestContext, operation: toolOperation },
            );
          }

          logger.info(`Executing tool: ${TOOL_NAME}`, requestContext);

          return await ErrorHandler.tryCatch<CallToolResult>(
            async () => {
              // Use the initialized accessor to get the working directory
              const sessionWorkingDirectory = _getWorkingDirectory(sessionId);

              const inputPath = validatedArgs.path;
              let resolvedPath: string;

              try {
                if (path.isAbsolute(inputPath)) {
                  resolvedPath = sanitization.sanitizePath(inputPath, {
                    allowAbsolute: true,
                  }).sanitizedPath;
                  logger.debug(
                    `Using absolute path: ${resolvedPath}`,
                    requestContext,
                  );
                } else if (sessionWorkingDirectory) {
                  resolvedPath = sanitization.sanitizePath(
                    path.resolve(sessionWorkingDirectory, inputPath),
                    { allowAbsolute: true },
                  ).sanitizedPath;
                  logger.debug(
                    `Resolved relative path '${inputPath}' to absolute path: ${resolvedPath} using session CWD`,
                    requestContext,
                  );
                } else {
                  // This case should now only be hit if the path is relative AND there's no session CWD set.
                  logger.error(
                    `Relative path '${inputPath}' provided but no session working directory is set.`,
                    requestContext,
                  );
                  throw new McpError(
                    BaseErrorCode.VALIDATION_ERROR,
                    `Relative path '${inputPath}' provided but no session working directory is set. Please provide an absolute path or set a working directory using git_set_working_dir.`,
                    { context: requestContext, operation: toolOperation },
                  );
                }
              } catch (error) {
                logger.error("Path resolution or sanitization failed", {
                  ...requestContext,
                  operation: toolOperation,
                  error,
                });
                if (error instanceof McpError) throw error;
                throw new McpError(
                  BaseErrorCode.VALIDATION_ERROR,
                  `Invalid path processing: ${error instanceof Error ? error.message : String(error)}`,
                  {
                    context: requestContext,
                    operation: toolOperation,
                    originalError: error,
                  },
                );
              }

              const logicArgs: GitInitInput = {
                ...validatedArgs,
                path: resolvedPath,
              };

              const initResult: GitInitResult = await gitInitLogic(
                logicArgs,
                requestContext,
              );

              const resultContent: TextContent = {
                type: "text",
                text: JSON.stringify(initResult, null, 2), // Pretty-print JSON
                contentType: "application/json",
              };

              logger.info(
                `Tool ${TOOL_NAME} executed successfully, returning JSON`,
                requestContext,
              );
              return { content: [resultContent] };
            },
            {
              operation: toolOperation,
              context: requestContext,
              input: validatedArgs,
              errorCode: BaseErrorCode.INTERNAL_ERROR,
            },
          );
        },
      );

      logger.info(`Tool registered: ${TOOL_NAME}`, context);
    },
    { operation, context, critical: true },
  );
};

import { BaseErrorCode, McpError } from "../../types-global/errors.js"; // Corrected path
import { logger } from "./logger.js";
import { sanitizeInputForLogging } from "../index.js"; // Import from main barrel file

/**
 * Generic error context interface
 */
export interface ErrorContext {
  /** Unique request or operation identifier */
  requestId?: string;
  /** Any additional context information */
  [key: string]: unknown;
}

/**
 * Error handler options
 */
export interface ErrorHandlerOptions {
  /** The context of the operation that caused the error */
  context?: ErrorContext;
  /** The name of the operation being performed */
  operation: string;
  /** The input that caused the error */
  input?: unknown;
  /** Whether to rethrow the error after handling */
  rethrow?: boolean;
  /** Custom error code to use when creating an McpError */
  errorCode?: BaseErrorCode;
  /** Custom error mapper function */
  errorMapper?: (error: unknown) => Error;
  /** Whether to include stack traces in logs */
  includeStack?: boolean;
  /** Whether this is a critical error that should abort operations */
  critical?: boolean;
}

/**
 * Base error mapping rule
 */
export interface BaseErrorMapping {
  /** Pattern to match in the error message */
  pattern: string | RegExp;
  /** Error code for mapped errors */
  errorCode: BaseErrorCode;
  /** Custom error message template */
  messageTemplate?: string;
}

/**
 * Error mapping configuration
 */
export interface ErrorMapping<T extends Error = Error>
  extends BaseErrorMapping {
  /** Factory function to create the mapped error */
  factory: (error: unknown, context?: Record<string, unknown>) => T;
  /** Additional context to merge with error context */
  additionalContext?: Record<string, unknown>;
}

/**
 * Simple mapper that maps error types to error codes
 */
const ERROR_TYPE_MAPPINGS: Record<string, BaseErrorCode> = {
  SyntaxError: BaseErrorCode.VALIDATION_ERROR,
  TypeError: BaseErrorCode.VALIDATION_ERROR,
  ReferenceError: BaseErrorCode.INTERNAL_ERROR,
  RangeError: BaseErrorCode.VALIDATION_ERROR,
  URIError: BaseErrorCode.VALIDATION_ERROR,
  EvalError: BaseErrorCode.INTERNAL_ERROR,
};

/**
 * Common error patterns for automatic classification
 */
const COMMON_ERROR_PATTERNS: BaseErrorMapping[] = [
  // Authentication related errors
  {
    pattern:
      /auth|unauthorized|unauthenticated|not.*logged.*in|invalid.*token|expired.*token/i,
    errorCode: BaseErrorCode.UNAUTHORIZED,
  },
  // Permission related errors
  {
    pattern: /permission|forbidden|access.*denied|not.*allowed/i,
    errorCode: BaseErrorCode.FORBIDDEN,
  },
  // Not found errors
  {
    pattern: /not.*found|missing|no.*such|doesn't.*exist|couldn't.*find/i,
    errorCode: BaseErrorCode.NOT_FOUND,
  },
  // Validation errors
  {
    pattern: /invalid|validation|malformed|bad request|wrong format/i,
    errorCode: BaseErrorCode.VALIDATION_ERROR,
  },
  // Conflict errors
  {
    pattern: /conflict|already.*exists|duplicate|unique.*constraint/i,
    errorCode: BaseErrorCode.CONFLICT,
  },
  // Rate limiting
  {
    pattern: /rate.*limit|too.*many.*requests|throttled/i,
    errorCode: BaseErrorCode.RATE_LIMITED,
  },
  // Timeout errors
  {
    pattern: /timeout|timed.*out|deadline.*exceeded/i,
    errorCode: BaseErrorCode.TIMEOUT,
  },
  // External service errors
  {
    pattern: /service.*unavailable|bad.*gateway|gateway.*timeout/i,
    errorCode: BaseErrorCode.SERVICE_UNAVAILABLE,
  },
];

/**
 * Get a readable name for an error
 * @param error Error to get name for
 * @returns User-friendly error name
 */
function getErrorName(error: unknown): string {
  if (error instanceof Error) {
    return error.name || "Error";
  }

  if (error === null) {
    return "NullError";
  }

  if (error === undefined) {
    return "UndefinedError";
  }

  return typeof error === "object" ? "ObjectError" : "UnknownError";
}

/**
 * Get a message from an error
 * @param error Error to get message from
 * @returns Error message
 */
function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }

  if (error === null) {
    return "Null error occurred";
  }

  if (error === undefined) {
    return "Undefined error occurred";
  }

  return typeof error === "string" ? error : String(error);
}

/**
 * Error handler utility class with various error handling methods
 */
export class ErrorHandler {
  /**
   * Determine the appropriate error code for an error based on patterns and type
   * @param error The error to classify
   * @returns The appropriate error code
   */
  public static determineErrorCode(error: unknown): BaseErrorCode {
    // If it's already an McpError, use its code
    if (error instanceof McpError) {
      return error.code;
    }

    const errorName = getErrorName(error);
    const errorMessage = getErrorMessage(error);

    // Check if the error type has a direct mapping
    if (errorName in ERROR_TYPE_MAPPINGS) {
      return ERROR_TYPE_MAPPINGS[errorName as keyof typeof ERROR_TYPE_MAPPINGS];
    }

    // Check for common error patterns
    for (const pattern of COMMON_ERROR_PATTERNS) {
      const regex =
        pattern.pattern instanceof RegExp
          ? pattern.pattern
          : new RegExp(pattern.pattern, "i");

      if (regex.test(errorMessage) || regex.test(errorName)) {
        return pattern.errorCode;
      }
    }

    // Default to internal error if no pattern matches
    return BaseErrorCode.INTERNAL_ERROR;
  }

  /**
   * Handle operation errors with consistent logging and transformation
   * @param error The error that occurred
   * @param options Error handling options
   * @returns The transformed error
   */
  public static handleError(
    error: unknown,
    options: ErrorHandlerOptions,
  ): Error {
    const {
      context,
      operation,
      input,
      rethrow = false,
      errorCode: explicitErrorCode,
      includeStack = true,
      critical = false,
    } = options;

    // If it's already an McpError, use it directly but apply additional context
    if (error instanceof McpError) {
      // Add any additional context
      if (context && Object.keys(context).length > 0) {
        // Ensure details is an object before spreading
        const existingDetails =
          typeof error.details === "object" && error.details !== null
            ? error.details
            : {};
        error.details = { ...existingDetails, ...context };
      }

      // Log the error with sanitized input
      logger.error(`Error ${operation}: ${error.message}`, {
        errorCode: error.code,
        requestId: context?.requestId,
        input: input ? sanitizeInputForLogging(input) : undefined,
        stack: includeStack ? error.stack : undefined,
        critical,
        ...context,
      });

      if (rethrow) {
        throw error;
      }

      // Ensure the function returns an Error type
      return error;
    }

    // Sanitize input for logging
    const sanitizedInput = input ? sanitizeInputForLogging(input) : undefined;

    // Log the error with consistent format
    logger.error(`Error ${operation}`, {
      error: getErrorMessage(error), // Use helper function
      errorType: getErrorName(error),
      input: sanitizedInput,
      requestId: context?.requestId,
      stack: includeStack && error instanceof Error ? error.stack : undefined,
      critical,
      ...context,
    });

    // Choose the error code (explicit > determined > default)
    const errorCode =
      explicitErrorCode ||
      ErrorHandler.determineErrorCode(error) ||
      BaseErrorCode.INTERNAL_ERROR;

    // Transform to appropriate error type
    let transformedError: Error;
    if (options.errorMapper) {
      transformedError = options.errorMapper(error);
    } else {
      transformedError = new McpError(
        errorCode,
        `Error ${operation}: ${getErrorMessage(error)}`, // Use helper function
        {
          originalError: getErrorName(error),
          ...context,
        },
      );
    }

    // Rethrow if requested
    if (rethrow) {
      throw transformedError;
    }

    // Ensure the function returns an Error type
    return transformedError;
  }

  /**
   * Map an error to a specific error type based on error message patterns
   * @param error The error to map
   * @param mappings Array of pattern and factory mappings
   * @param defaultFactory Default factory function if no pattern matches
   * @returns The mapped error
   */
  public static mapError<T extends Error>(
    error: unknown,
    mappings: ErrorMapping<T>[],
    defaultFactory?: (error: unknown, context?: Record<string, unknown>) => T,
  ): T | Error {
    // If it's already the target type and we have a default factory to check against, return it
    if (defaultFactory && error instanceof Error) {
      const defaultInstance = defaultFactory(error);
      if (error.constructor === defaultInstance.constructor) {
        return error as T;
      }
    }

    const errorMessage = getErrorMessage(error);

    // Check each pattern and return the first match
    for (const mapping of mappings) {
      const matches =
        mapping.pattern instanceof RegExp
          ? mapping.pattern.test(errorMessage)
          : errorMessage.includes(mapping.pattern);

      if (matches) {
        return mapping.factory(error, mapping.additionalContext);
      }
    }

    // Return default or original error
    if (defaultFactory) {
      return defaultFactory(error);
    }

    return error instanceof Error ? error : new Error(String(error));
  }

  // Removed createErrorMapper method for simplification

  /**
   * Format an error for consistent response structure
   * @param error The error to format
   * @returns Formatted error object
   */
  public static formatError(error: unknown): Record<string, unknown> {
    if (error instanceof McpError) {
      return {
        code: error.code,
        message: error.message,
        // Ensure details is an object
        details:
          typeof error.details === "object" && error.details !== null
            ? error.details
            : {},
      };
    }

    if (error instanceof Error) {
      return {
        code: ErrorHandler.determineErrorCode(error),
        message: error.message,
        details: { errorType: error.name },
      };
    }

    return {
      code: BaseErrorCode.UNKNOWN_ERROR,
      message: String(error),
      details: { errorType: typeof error },
    };
  }

  /**
   * Safely execute a function and handle any errors
   * @param fn Function to execute
   * @param options Error handling options
   * @returns The result of the function or error
   */
  public static async tryCatch<T>(
    fn: () => Promise<T> | T,
    options: ErrorHandlerOptions,
  ): Promise<T> {
    try {
      return await fn();
    } catch (error) {
      throw ErrorHandler.handleError(error, { ...options, rethrow: true });
    }
  }
}

/**
 * @fileoverview Barrel file for the git_init tool.
 * Exports the registration function and the state accessor initializer.
 */

export {
  registerGitInitTool,
  initializeGitInitStateAccessors,
} from "./registration.js";
// Export types if needed elsewhere, e.g.:
// export type { GitInitInput, GitInitResult } from './logic.js';

import { execFile } from "child_process";
import fs from "fs/promises";
import path from "path";
import { promisify } from "util";
import { z } from "zod";
// Import utils from barrel (logger from ../utils/internal/logger.js)
import { logger } from "../../../utils/index.js";
// Import utils from barrel (RequestContext from ../utils/internal/requestContext.js)
import { BaseErrorCode, McpError } from "../../../types-global/errors.js"; // Keep direct import for types-global
import { RequestContext } from "../../../utils/index.js";
// Import utils from barrel (sanitization from ../utils/security/sanitization.js)
import { sanitization } from "../../../utils/index.js";

const execFileAsync = promisify(execFile);

// Define the input schema for the git_init tool using Zod
export const GitInitInputSchema = z.object({
  path: z
    .string()
    .min(1)
    .optional()
    .default(".")
    .describe(
      "Path where the new Git repository should be initialized. Can be relative or absolute. If relative or '.', it resolves against the directory set via `git_set_working_dir` for the session. If absolute, it's used directly. If omitted, defaults to '.' (resolved against session git working directory).",
    ),
  initialBranch: z
    .string()
    .optional()
    .describe(
      "Optional name for the initial branch (e.g., 'main'). Uses Git's default if not specified.",
    ),
  bare: z
    .boolean()
    .default(false)
    .describe("Create a bare repository (no working directory)."),
  quiet: z
    .boolean()
    .default(false)
    .describe(
      "Only print error and warning messages; all other output will be suppressed.",
    ),
});

// Infer the TypeScript type from the Zod schema
export type GitInitInput = z.infer<typeof GitInitInputSchema>;

// Define the structure for the JSON output
export interface GitInitResult {
  success: boolean;
  message: string;
  path: string; // The path where the repo was initialized
  gitDirExists: boolean; // Confirms the .git directory was created (or equivalent for bare)
}

/**
 * Executes the 'git init' command to initialize a new Git repository.
 *
 * @param {GitInitInput} input - The validated input object.
 * @param {RequestContext} context - The request context for logging and error handling.
 * @returns {Promise<GitInitResult>} A promise that resolves with the structured init result.
 * @throws {McpError} Throws an McpError if path validation fails or the git command fails unexpectedly.
 */
export async function gitInitLogic(
  input: GitInitInput,
  context: RequestContext,
): Promise<GitInitResult> {
  const operation = "gitInitLogic";
  logger.debug(`Executing ${operation}`, { ...context, input });

  let targetPath: string;
  try {
    // Sanitize the provided absolute path
    targetPath = sanitization.sanitizePath(input.path, {
      allowAbsolute: true,
    }).sanitizedPath;
    logger.debug("Sanitized path", {
      ...context,
      operation,
      sanitizedPath: targetPath,
    });

    // Ensure the target directory exists before trying to init inside it
    // git init creates the directory if it doesn't exist, but we might want to ensure the parent exists
    const parentDir = path.dirname(targetPath);
    try {
      await fs.access(parentDir, fs.constants.W_OK); // Check write access in parent
    } catch (accessError: any) {
      logger.error(`Parent directory check failed for ${targetPath}`, {
        ...context,
        operation,
        error: accessError.message,
      });
      if (accessError.code === "ENOENT") {
        throw new McpError(
          BaseErrorCode.VALIDATION_ERROR,
          `Parent directory does not exist: ${parentDir}`,
          { context, operation },
        );
      }
      throw new McpError(
        BaseErrorCode.VALIDATION_ERROR,
        `Cannot access parent directory: ${parentDir}. Error: ${accessError.message}`,
        { context, operation },
      );
    }
  } catch (error) {
    logger.error("Path validation or sanitization failed", {
      ...context,
      operation,
      error,
    });
    if (error instanceof McpError) throw error;
    throw new McpError(
      BaseErrorCode.VALIDATION_ERROR,
      `Invalid path: ${error instanceof Error ? error.message : String(error)}`,
      { context, operation, originalError: error },
    );
  }

  try {
    // Construct the git init command
    const args: string[] = ["init"];
    if (input.quiet) {
      args.push("--quiet");
    }
    if (input.bare) {
      args.push("--bare");
    }
    // Determine the initial branch name, defaulting to 'main' if not provided
    const branchNameToUse = input.initialBranch || "main";
    args.push("-b", branchNameToUse);

    // Add the target directory path at the end
    args.push(targetPath);

    logger.debug(`Executing command: git ${args.join(" ")}`, {
      ...context,
      operation,
    });

    const { stdout, stderr } = await execFileAsync("git", args);

    if (stderr && !input.quiet) {
      // Log stderr as warning but proceed, as init might still succeed (e.g., reinitializing)
      logger.warning(`Git init command produced stderr`, {
        ...context,
        operation,
        stderr,
      });
    }
    if (stdout && !input.quiet) {
      // Log stdout at debug level for cleaner info logs
      logger.debug(`Git init command produced stdout`, {
        ...context,
        operation,
        stdout,
      });
    }

    // Verify .git directory exists (or equivalent for bare repo)
    const gitDirPath = input.bare ? targetPath : path.join(targetPath, ".git");
    let gitDirExists = false;
    try {
      await fs.access(gitDirPath);
      gitDirExists = true;
    } catch (e) {
      logger.warning(
        `Could not verify existence of ${gitDirPath} after git init`,
        { ...context, operation },
      );
    }

    const successMessage = `Successfully initialized Git repository in ${targetPath}`;
    logger.info(successMessage, {
      ...context,
      operation,
      path: targetPath,
      bare: input.bare,
      initialBranch: input.initialBranch || "default",
    });
    return {
      success: true,
      message: stdout.trim() || successMessage, // Return stdout to user if available
      path: targetPath,
      gitDirExists: gitDirExists,
    };
  } catch (error: any) {
    const errorMessage = error.stderr || error.message || "";
    logger.error(`Failed to execute git init command`, {
      ...context,
      operation,
      path: targetPath,
      error: errorMessage,
      stderr: error.stderr,
      stdout: error.stdout,
    });

    // Handle specific error cases
    if (
      errorMessage.toLowerCase().includes("already exists") &&
      errorMessage.toLowerCase().includes("git repository")
    ) {
      // Reinitializing is often okay, treat as success but mention it.
      logger.info(`Repository already exists, reinitialized: ${targetPath}`, {
        ...context,
        operation,
      });
      return {
        success: true, // Treat reinitialization as success
        message: `Reinitialized existing Git repository in ${targetPath}`,
        path: targetPath,
        gitDirExists: true, // Assume it exists if reinit message appears
      };
    }
    if (errorMessage.toLowerCase().includes("permission denied")) {
      throw new McpError(
        BaseErrorCode.FORBIDDEN,
        `Permission denied to initialize repository at: ${targetPath}. Error: ${errorMessage}`,
        { context, operation, originalError: error },
      );
    }

    // Generic internal error for other failures
    throw new McpError(
      BaseErrorCode.INTERNAL_ERROR,
      `Failed to initialize repository at: ${targetPath}. Error: ${errorMessage}`,
      { context, operation, originalError: error },
    );
  }
}

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import {
  CallToolResult,
  TextContent,
} from "@modelcontextprotocol/sdk/types.js";
import path from "path";
import { z } from "zod";
import { BaseErrorCode, McpError } from "../../../types-global/errors.js";
import {
  ErrorHandler,
  logger,
  requestContextService,
  sanitization,
} from "../../../utils/index.js";
import {
  GitInitInput,
  GitInitInputSchema,
  gitInitLogic,
  GitInitResult,
} from "./logic.js";

const TOOL_NAME = "git_init";
const TOOL_DESCRIPTION =
  "Initializes a new Git repository at the specified path. If path is relative or omitted, it resolves against the session working directory (if you have set the git_working_dir). Can optionally set the initial branch name and create a bare repository.";

const RegistrationSchema = GitInitInputSchema.extend({
  path: z.string().min(1).optional().default("."),
}).shape;

// --- Module-level State Accessors ---
// These will be populated by the initialize function called from server.ts
let _getWorkingDirectory: (
  sessionId: string | undefined,
) => string | undefined = () => undefined;
let _getSessionIdFromContext: (
  context: Record<string, any>,
) => string | undefined = () => undefined;

/**
 * Initializes state accessor functions for the git_init tool.
 * This function is called by the main server setup to provide the tool
 * with a way to access session-specific state (like the working directory)
 * without needing direct access to the server or transport layer internals.
 *
 * @param getWorkingDirectory - Function to retrieve the working directory for a given session ID.
 * @param getSessionIdFromContext - Function to extract the session ID from a tool's execution context.
 */
export function initializeGitInitStateAccessors(
  getWorkingDirectory: (sessionId: string | undefined) => string | undefined,
  getSessionIdFromContext: (context: Record<string, any>) => string | undefined,
): void {
  _getWorkingDirectory = getWorkingDirectory;
  _getSessionIdFromContext = getSessionIdFromContext;
  logger.debug(`State accessors initialized for ${TOOL_NAME}`);
}

/**
 * Registers the git_init tool with the MCP server.
 *
 * @param {McpServer} server - The McpServer instance to register the tool with.
 * @returns {Promise<void>}
 * @throws {Error} If registration fails.
 */
export const registerGitInitTool = async (server: McpServer): Promise<void> => {
  const operation = "registerGitInitTool";
  const context = requestContextService.createRequestContext({ operation });

  await ErrorHandler.tryCatch(
    async () => {
      server.tool<typeof RegistrationSchema>(
        TOOL_NAME,
        TOOL_DESCRIPTION,
        RegistrationSchema,
        async (validatedArgs, callContext): Promise<CallToolResult> => {
          // Removed explicit type for callContext
          const toolOperation = "tool:git_init";
          const requestContext = requestContextService.createRequestContext({
            operation: toolOperation,
            parentContext: callContext,
          });

          // Use the initialized accessor to get the session ID
          const sessionId = _getSessionIdFromContext(requestContext); // Pass the created context
          if (!sessionId && !path.isAbsolute(validatedArgs.path)) {
            // If path is relative, we NEED a session ID to resolve against a potential working dir
            logger.error(
              "Session ID is missing in context, cannot resolve relative path",
              requestContext,
            );
            throw new McpError(
              BaseErrorCode.INTERNAL_ERROR,
              "Session context is unavailable for relative path resolution.",
              { context: requestContext, operation: toolOperation },
            );
          }

          logger.info(`Executing tool: ${TOOL_NAME}`, requestContext);

          return await ErrorHandler.tryCatch<CallToolResult>(
            async () => {
              // Use the initialized accessor to get the working directory
              const sessionWorkingDirectory = _getWorkingDirectory(sessionId);

              const inputPath = validatedArgs.path;
              let resolvedPath: string;

              try {
                if (path.isAbsolute(inputPath)) {
                  resolvedPath = sanitization.sanitizePath(inputPath, {
                    allowAbsolute: true,
                  }).sanitizedPath;
                  logger.debug(
                    `Using absolute path: ${resolvedPath}`,
                    requestContext,
                  );
                } else if (sessionWorkingDirectory) {
                  resolvedPath = sanitization.sanitizePath(
                    path.resolve(sessionWorkingDirectory, inputPath),
                    { allowAbsolute: true },
                  ).sanitizedPath;
                  logger.debug(
                    `Resolved relative path '${inputPath}' to absolute path: ${resolvedPath} using session CWD`,
                    requestContext,
                  );
                } else {
                  // This case should now only be hit if the path is relative AND there's no session CWD set.
                  logger.error(
                    `Relative path '${inputPath}' provided but no session working directory is set.`,
                    requestContext,
                  );
                  throw new McpError(
                    BaseErrorCode.VALIDATION_ERROR,
                    `Relative path '${inputPath}' provided but no session working directory is set. Please provide an absolute path or set a working directory using git_set_working_dir.`,
                    { context: requestContext, operation: toolOperation },
                  );
                }
              } catch (error) {
                logger.error("Path resolution or sanitization failed", {
                  ...requestContext,
                  operation: toolOperation,
                  error,
                });
                if (error instanceof McpError) throw error;
                throw new McpError(
                  BaseErrorCode.VALIDATION_ERROR,
                  `Invalid path processing: ${error instanceof Error ? error.message : String(error)}`,
                  {
                    context: requestContext,
                    operation: toolOperation,
                    originalError: error,
                  },
                );
              }

              const logicArgs: GitInitInput = {
                ...validatedArgs,
                path: resolvedPath,
              };

              const initResult: GitInitResult = await gitInitLogic(
                logicArgs,
                requestContext,
              );

              const resultContent: TextContent = {
                type: "text",
                text: JSON.stringify(initResult, null, 2), // Pretty-print JSON
                contentType: "application/json",
              };

              logger.info(
                `Tool ${TOOL_NAME} executed successfully, returning JSON`,
                requestContext,
              );
              return { content: [resultContent] };
            },
            {
              operation: toolOperation,
              context: requestContext,
              input: validatedArgs,
              errorCode: BaseErrorCode.INTERNAL_ERROR,
            },
          );
        },
      );

      logger.info(`Tool registered: ${TOOL_NAME}`, context);
    },
    { operation, context, critical: true },
  );
};

import { BaseErrorCode, McpError } from "../../types-global/errors.js"; // Corrected path
import { logger } from "./logger.js";
import { sanitizeInputForLogging } from "../index.js"; // Import from main barrel file

/**
 * Generic error context interface
 */
export interface ErrorContext {
  /** Unique request or operation identifier */
  requestId?: string;
  /** Any additional context information */
  [key: string]: unknown;
}

/**
 * Error handler options
 */
export interface ErrorHandlerOptions {
  /** The context of the operation that caused the error */
  context?: ErrorContext;
  /** The name of the operation being performed */
  operation: string;
  /** The input that caused the error */
  input?: unknown;
  /** Whether to rethrow the error after handling */
  rethrow?: boolean;
  /** Custom error code to use when creating an McpError */
  errorCode?: BaseErrorCode;
  /** Custom error mapper function */
  errorMapper?: (error: unknown) => Error;
  /** Whether to include stack traces in logs */
  includeStack?: boolean;
  /** Whether this is a critical error that should abort operations */
  critical?: boolean;
}

/**
 * Base error mapping rule
 */
export interface BaseErrorMapping {
  /** Pattern to match in the error message */
  pattern: string | RegExp;
  /** Error code for mapped errors */
  errorCode: BaseErrorCode;
  /** Custom error message template */
  messageTemplate?: string;
}

/**
 * Error mapping configuration
 */
export interface ErrorMapping<T extends Error = Error>
  extends BaseErrorMapping {
  /** Factory function to create the mapped error */
  factory: (error: unknown, context?: Record<string, unknown>) => T;
  /** Additional context to merge with error context */
  additionalContext?: Record<string, unknown>;
}

/**
 * Simple mapper that maps error types to error codes
 */
const ERROR_TYPE_MAPPINGS: Record<string, BaseErrorCode> = {
  SyntaxError: BaseErrorCode.VALIDATION_ERROR,
  TypeError: BaseErrorCode.VALIDATION_ERROR,
  ReferenceError: BaseErrorCode.INTERNAL_ERROR,
  RangeError: BaseErrorCode.VALIDATION_ERROR,
  URIError: BaseErrorCode.VALIDATION_ERROR,
  EvalError: BaseErrorCode.INTERNAL_ERROR,
};

/**
 * Common error patterns for automatic classification
 */
const COMMON_ERROR_PATTERNS: BaseErrorMapping[] = [
  // Authentication related errors
  {
    pattern:
      /auth|unauthorized|unauthenticated|not.*logged.*in|invalid.*token|expired.*token/i,
    errorCode: BaseErrorCode.UNAUTHORIZED,
  },
  // Permission related errors
  {
    pattern: /permission|forbidden|access.*denied|not.*allowed/i,
    errorCode: BaseErrorCode.FORBIDDEN,
  },
  // Not found errors
  {
    pattern: /not.*found|missing|no.*such|doesn't.*exist|couldn't.*find/i,
    errorCode: BaseErrorCode.NOT_FOUND,
  },
  // Validation errors
  {
    pattern: /invalid|validation|malformed|bad request|wrong format/i,
    errorCode: BaseErrorCode.VALIDATION_ERROR,
  },
  // Conflict errors
  {
    pattern: /conflict|already.*exists|duplicate|unique.*constraint/i,
    errorCode: BaseErrorCode.CONFLICT,
  },
  // Rate limiting
  {
    pattern: /rate.*limit|too.*many.*requests|throttled/i,
    errorCode: BaseErrorCode.RATE_LIMITED,
  },
  // Timeout errors
  {
    pattern: /timeout|timed.*out|deadline.*exceeded/i,
    errorCode: BaseErrorCode.TIMEOUT,
  },
  // External service errors
  {
    pattern: /service.*unavailable|bad.*gateway|gateway.*timeout/i,
    errorCode: BaseErrorCode.SERVICE_UNAVAILABLE,
  },
];

/**
 * Get a readable name for an error
 * @param error Error to get name for
 * @returns User-friendly error name
 */
function getErrorName(error: unknown): string {
  if (error instanceof Error) {
    return error.name || "Error";
  }

  if (error === null) {
    return "NullError";
  }

  if (error === undefined) {
    return "UndefinedError";
  }

  return typeof error === "object" ? "ObjectError" : "UnknownError";
}

/**
 * Get a message from an error
 * @param error Error to get message from
 * @returns Error message
 */
function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }

  if (error === null) {
    return "Null error occurred";
  }

  if (error === undefined) {
    return "Undefined error occurred";
  }

  return typeof error === "string" ? error : String(error);
}

/**
 * Error handler utility class with various error handling methods
 */
export class ErrorHandler {
  /**
   * Determine the appropriate error code for an error based on patterns and type
   * @param error The error to classify
   * @returns The appropriate error code
   */
  public static determineErrorCode(error: unknown): BaseErrorCode {
    // If it's already an McpError, use its code
    if (error instanceof McpError) {
      return error.code;
    }

    const errorName = getErrorName(error);
    const errorMessage = getErrorMessage(error);

    // Check if the error type has a direct mapping
    if (errorName in ERROR_TYPE_MAPPINGS) {
      return ERROR_TYPE_MAPPINGS[errorName as keyof typeof ERROR_TYPE_MAPPINGS];
    }

    // Check for common error patterns
    for (const pattern of COMMON_ERROR_PATTERNS) {
      const regex =
        pattern.pattern instanceof RegExp
          ? pattern.pattern
          : new RegExp(pattern.pattern, "i");

      if (regex.test(errorMessage) || regex.test(errorName)) {
        return pattern.errorCode;
      }
    }

    // Default to internal error if no pattern matches
    return BaseErrorCode.INTERNAL_ERROR;
  }

  /**
   * Handle operation errors with consistent logging and transformation
   * @param error The error that occurred
   * @param options Error handling options
   * @returns The transformed error
   */
  public static handleError(
    error: unknown,
    options: ErrorHandlerOptions,
  ): Error {
    const {
      context,
      operation,
      input,
      rethrow = false,
      errorCode: explicitErrorCode,
      includeStack = true,
      critical = false,
    } = options;

    // If it's already an McpError, use it directly but apply additional context
    if (error instanceof McpError) {
      // Add any additional context
      if (context && Object.keys(context).length > 0) {
        // Ensure details is an object before spreading
        const existingDetails =
          typeof error.details === "object" && error.details !== null
            ? error.details
            : {};
        error.details = { ...existingDetails, ...context };
      }

      // Log the error with sanitized input
      logger.error(`Error ${operation}: ${error.message}`, {
        errorCode: error.code,
        requestId: context?.requestId,
        input: input ? sanitizeInputForLogging(input) : undefined,
        stack: includeStack ? error.stack : undefined,
        critical,
        ...context,
      });

      if (rethrow) {
        throw error;
      }

      // Ensure the function returns an Error type
      return error;
    }

    // Sanitize input for logging
    const sanitizedInput = input ? sanitizeInputForLogging(input) : undefined;

    // Log the error with consistent format
    logger.error(`Error ${operation}`, {
      error: getErrorMessage(error), // Use helper function
      errorType: getErrorName(error),
      input: sanitizedInput,
      requestId: context?.requestId,
      stack: includeStack && error instanceof Error ? error.stack : undefined,
      critical,
      ...context,
    });

    // Choose the error code (explicit > determined > default)
    const errorCode =
      explicitErrorCode ||
      ErrorHandler.determineErrorCode(error) ||
      BaseErrorCode.INTERNAL_ERROR;

    // Transform to appropriate error type
    let transformedError: Error;
    if (options.errorMapper) {
      transformedError = options.errorMapper(error);
    } else {
      transformedError = new McpError(
        errorCode,
        `Error ${operation}: ${getErrorMessage(error)}`, // Use helper function
        {
          originalError: getErrorName(error),
          ...context,
        },
      );
    }

    // Rethrow if requested
    if (rethrow) {
      throw transformedError;
    }

    // Ensure the function returns an Error type
    return transformedError;
  }

  /**
   * Map an error to a specific error type based on error message patterns
   * @param error The error to map
   * @param mappings Array of pattern and factory mappings
   * @param defaultFactory Default factory function if no pattern matches
   * @returns The mapped error
   */
  public static mapError<T extends Error>(
    error: unknown,
    mappings: ErrorMapping<T>[],
    defaultFactory?: (error: unknown, context?: Record<string, unknown>) => T,
  ): T | Error {
    // If it's already the target type and we have a default factory to check against, return it
    if (defaultFactory && error instanceof Error) {
      const defaultInstance = defaultFactory(error);
      if (error.constructor === defaultInstance.constructor) {
        return error as T;
      }
    }

    const errorMessage = getErrorMessage(error);

    // Check each pattern and return the first match
    for (const mapping of mappings) {
      const matches =
        mapping.pattern instanceof RegExp
          ? mapping.pattern.test(errorMessage)
          : errorMessage.includes(mapping.pattern);

      if (matches) {
        return mapping.factory(error, mapping.additionalContext);
      }
    }

    // Return default or original error
    if (defaultFactory) {
      return defaultFactory(error);
    }

    return error instanceof Error ? error : new Error(String(error));
  }

  // Removed createErrorMapper method for simplification

  /**
   * Format an error for consistent response structure
   * @param error The error to format
   * @returns Formatted error object
   */
  public static formatError(error: unknown): Record<string, unknown> {
    if (error instanceof McpError) {
      return {
        code: error.code,
        message: error.message,
        // Ensure details is an object
        details:
          typeof error.details === "object" && error.details !== null
            ? error.details
            : {},
      };
    }

    if (error instanceof Error) {
      return {
        code: ErrorHandler.determineErrorCode(error),
        message: error.message,
        details: { errorType: error.name },
      };
    }

    return {
      code: BaseErrorCode.UNKNOWN_ERROR,
      message: String(error),
      details: { errorType: typeof error },
    };
  }

  /**
   * Safely execute a function and handle any errors
   * @param fn Function to execute
   * @param options Error handling options
   * @returns The result of the function or error
   */
  public static async tryCatch<T>(
    fn: () => Promise<T> | T,
    options: ErrorHandlerOptions,
  ): Promise<T> {
    try {
      return await fn();
    } catch (error) {
      throw ErrorHandler.handleError(error, { ...options, rethrow: true });
    }
  }
}

